def externalize_media(markup,prefix):
 if REMOTE.get('preferencia')!='externo':return markup
 def replace_tag(match):
  tag=match.group(0)
  name=match.group(1)
  # O download explícito continua sendo a alternativa local.
  if name=='a' and re.search(r'\sdownload(?:[\s=>])',tag):return tag
  attribute='href' if name=='a' else 'poster' if name=='video' else 'src'
  found=re.search(r'\s'+attribute+r'="([^"]+)"',tag)
  if not found:return tag
  original=html.unescape(found.group(1))
  local=original[len(prefix):] if prefix and original.startswith(prefix) else original
  entry=REMOTE['recursos'].get(local)
  if not entry or not entry.get('disponivel'):return tag
  fallback='data-local-href' if name=='a' else 'data-local-poster' if name=='video' else 'data-local-src'
  replacement=f' {attribute}="{e(entry["url"])}" {fallback}="{e(original)}"'
  tag=tag[:found.start()]+replacement+tag[found.end():]
  if name=='a' and 'data-gallery-link' not in tag and 'target=' not in tag:
   tag=tag[:-1]+' target="_blank" rel="noopener noreferrer">'
  return tag
 return re.sub(r'<(img|source|video|a)\b[^>]*>',replace_tag,markup)


