def impact_panel(default=100):
 selected=next(item for item in IMPACTS if item['valor']==default)
 body=f'''<div class="impact-panel"><div class="impact-selector"><p class="eyebrow">Escolha sua contribuição</p><p class="impact-value" id="impactAmount">R$ {default}</p><div class="impact-options" role="group" aria-label="Valor da contribuição">'''
 for item in IMPACTS:
  value=item['valor']
  body+=f'<button type="button" data-impact-amount="{value}" data-impact-title="{e(item["titulo"])}" data-impact-description="{e(item["descricao"])}" aria-pressed="{str(value==default).lower()}" class="{"is-selected" if value==default else ""}">R$ {value}</button>'
 body+=f'''</div><div class="impact-result" aria-live="polite" aria-atomic="true"><p class="impact-result-label">Esse valor pode ajudar com</p><h3 id="impactSummary">{e(selected['titulo'])}</h3><p class="impact-note" id="impactDescription">{e(selected['descricao'])}</p></div><button class="btn btn-light donate-trigger impact-donate" type="button" data-impact-donate data-amount="{default}">Quero contribuir com R$ {default}</button></div><ul class="impact-list list-unstyled" aria-label="Exemplos de como sua contribuição pode ajudar">'''
 for item in IMPACTS:
  active=item['valor']==default
  body+=f'<li data-impact-example="{item["valor"]}" class="{"is-selected" if active else ""}"><span class="impact-price">R$ {item["valor"]}</span><div><h3>{e(item["titulo"])}<span class="visually-hidden" data-impact-selected{("" if active else " hidden")}> — exemplo selecionado</span></h3><p>{e(item["itens"])}</p></div></li>'
 return body+f'</ul></div><p class="impact-estimate">{e(IMPACT_RESEARCH["observacao"])}</p>'


