 body+=f'''<section class="impact-section home-impact" id="impacto"><div class="container site-container">{heading('Seu gesto importa','Veja o que sua doação pode fazer.','Da aprendizagem à alimentação, cada contribuição ajuda a transformar o dia a dia. Escolha um valor e veja um exemplo.')}{impact_panel()}</div></section>'''
 body+=f'''<section class="section-block home-news"><div class="container site-container"><div class="heading-with-action">{heading('Acompanhe de perto','Histórias que dão sentido ao cuidado.','O dia a dia, as iniciativas e os encontros da AACI.')}{link('Todas as notícias','noticias.html')}</div><div class="stories-grid">{''.join(news_card(n) for n in RESEARCH['noticias'][:3])}</div></div></section><section class="home-transparency"><div class="container site-container"><div class="trust-banner"><div><p class="eyebrow">Uma relação aberta com quem apoia</p><h2>Cuidado também se faz com transparência.</h2><p>Consulte nossos relatórios, documentos institucionais e prestações de contas.</p></div>{link('Acesse os documentos','transparencia.html',style='btn btn-light')}</div></div></section>'''
