def about():
 body=intro('Uma história feita de pessoas.','Quem somos','Desde 2010, a AACI constrói caminhos de cuidado e convivência com a comunidade.','', 'fachada')
 body+=f'''<section class="section-block"><div class="container site-container"><div class="split-layout about-purpose"><div>{heading('Nosso propósito','Estar perto. Escutar. Cuidar.')}<p class="lead-copy">Somos uma organização sem fins lucrativos que atua na proteção social e no fortalecimento de vínculos familiares e comunitários.</p><p>Nosso trabalho reúne crianças, adolescentes, mulheres, pessoas idosas e famílias. Criamos espaços para acolher, aprender, conviver e desenvolver potencialidades.</p></div><div class="value-cards"><article><span class="round-icon">{icon('heart')}</span><h3>Missão</h3><p>Oferecer cuidado, acolhimento e atividades educativas que apoiem as famílias no enfrentamento da vulnerabilidade social.</p></article><article><span class="round-icon">{icon('people')}</span><h3>Visão</h3><p>Ampliar o acesso a serviços e oportunidades, contribuindo para reduzir as desigualdades sociais.</p></article></div></div><div class="values-strip"><strong>Nossos valores</strong><span>Respeito</span><span>Ética</span><span>Escuta ativa</span><span>Dedicação</span><span>União</span><span>Garantia de direitos</span></div></div></section>'''
 body+='<section class="section-block cream-section"><div class="container site-container">'+heading('Nossa trajetória','Cada passo, uma nova possibilidade.')+'<ol class="timeline">'
 for year,title,text in [('2010','O começo da nossa história','A AACI inicia sua atuação em Juiz de Fora, junto às crianças, pessoas idosas e suas famílias.'),('2015','Convivência e fortalecimento de vínculos','O SCFV amplia os espaços de participação, desenvolvimento e convivência comunitária.'),('2018','Criança Esperança','A instituição recebe o apoio do projeto social da TV Globo para a continuidade de suas ações.'),('2021','Novas possibilidades digitais','O incentivo da Becton Dickinson contribui para a criação da sala de informática.'),('2024','Um legado de atuação','A trajetória inclui a execução do SCFV em Guarulhos/SP e a mobilização solidária em apoio ao Rio Grande do Sul.')]:body+=f'<li><span>{year}</span><div><h3>{title}</h3><p>{text}</p></div></li>'
 body+='</ol></div></section>'
 body+=f'''<section class="section-block"><div class="container site-container">{heading('Espaços de convivência','Um lugar para aprender e compartilhar.')}<div class="photo-strip">{img('sala-atividades')}{img('informatica')}{img('refeitorio')}</div><div class="section-end">{link('Veja nossa galeria','galeria.html')}</div></div></section><section class="section-block cream-section"><div class="container site-container">{heading('Quem faz parte','Pessoas que constroem essa história.')}<div class="team-grid"><article class="plain-card"><p class="eyebrow">Presidência</p><h3>Hugo Leonardo Toribio de Oliveira</h3><p>Presidente da Associação</p></article><article class="plain-card"><p class="eyebrow">Administração</p><h3>Josiel Alves de Oliveira Santos</h3><p>Diretor Administrativo-Financeiro</p></article><article class="plain-card"><p class="eyebrow">Captação de recursos</p><h3>Soraia Dorcas</h3><p>Gerente de Telemarketing</p></article></div></div></section>'''
 body+='<section class="section-block" id="parceiros"><div class="container site-container">'+heading('Rede de apoio','Organizações presentes em nossa trajetória.','A solidariedade ganha força quando é compartilhada.',True)+'<div class="partners-grid">'
 for a in MAP['parceiros']:body+=f'<div class="partner-logo"><img src="{e(a["path"])}" alt="{e(a.get("name",a.get("alt",a.get("nome","Parceiro da AACI"))))}" width="{a.get("width",300)}" height="{a.get("height",150)}" loading="lazy"></div>'
 body+='</div></div></section>'+callout()
 write_page('quem-somos.html','Quem somos','Nossa história, missão, valores, equipe e rede de apoio. Conheça a AACI e seus espaços de convivência.',body)


def services():
 body=intro('Cuidado que acompanha cada fase da vida.','O que fazemos','Serviços, projetos e encontros que fortalecem pessoas, famílias e comunidade.')
 body+='<section class="services section-block"><div class="container site-container">'+service_grid()+'</div></section>'
 body+=f'''<section class="section-block cream-section" id="campanhas"><div class="container site-container"><div class="split-layout"><div>{heading('Solidariedade em movimento','Quando a comunidade se une, o cuidado chega mais longe.')}<p class="lead-copy">Campanhas de alimentos, brinquedos e itens essenciais ajudam a apoiar famílias em diferentes momentos.</p><p>Nossa trajetória inclui ações de Natal Solidário, mobilizações em apoio ao Rio Grande do Sul e iniciativas de segurança alimentar.</p>{link('Saiba como participar','como-ajudar.html')}</div><div class="rounded-photo">{img('campanhas')}</div></div></div></section><section class="section-block"><div class="container site-container">{heading('Alimentação e comunidade','Uma rede de cuidado à mesa.','Registro da entrega de cestas básicas por meio do Programa Comunidade, Presente!, do Itaú Social, em 2021.')}<div class="video-reading-width">{yt_player('NBQDaKdFK5c')}</div></div></section><section class="section-block cream-section" id="cozinhas"><div class="container site-container"><div class="split-layout"><div class="rounded-photo">{img('cozinha')}</div><div>{heading('Segurança alimentar','Cozinhas comunitárias: alimento e acolhimento.')}<p>Em julho de 2026, a AACI compartilhou a notícia da gestão de três cozinhas comunitárias em Muriaé, fortalecendo suas ações de combate à insegurança alimentar.</p>{link('Conheça essa iniciativa','noticias/cozinha-comunitaria.html')}</div></div></div></section>'''+callout()
 write_page('servicos.html','O que fazemos','Conheça os serviços da AACI: convivência, pessoa idosa, apadrinhamento, fisioterapia e campanhas solidárias.',body)


def service_details():
 body=intro('Convivência que fortalece vínculos.','Convivência e vínculos','Um espaço de participação, descobertas e desenvolvimento para crianças, adolescentes, mulheres e pessoas idosas.','', 'convivencia')
 body+=f'''<section class="section-block"><div class="container site-container"><div class="split-layout"><div>{heading('SCFV','Crescer, aprender e pertencer.')}<p class="lead-copy">O Serviço de Convivência e Fortalecimento de Vínculos reúne atividades de arte, esporte, cultura e lazer, com atendimento gratuito.</p><p>Acolhida, escuta e acompanhamento social ajudam a fortalecer a autonomia, os vínculos familiares e a participação na comunidade.</p>{external('Converse sobre a participação',wa('Olá! Gostaria de saber como participar do Serviço de Convivência da AACI.'))}</div><aside class="plain-card audience-card"><p class="eyebrow">Para quem</p><h3>Uma comunidade de diferentes gerações</h3><ul><li>Crianças de 4 a 14 anos</li><li>Adolescentes de 14 a 17 anos</li><li>Mulheres a partir de 18 anos</li><li>Pessoas idosas acima de 60 anos</li></ul><p class="small-note">A equipe orienta sobre encaminhamentos, inscrições e disponibilidade de vagas.</p></aside></div></div></section><section class="section-block cream-section" id="atividades"><div class="container site-container">{heading('Aprender fazendo','Atividades que abrem novas possibilidades.')}<div class="feature-grid">'''
 for ic,title,text in [('food','Oficina Master Chef','Receitas e descobertas sobre alimentação, cultura e cuidado.'),('palette','Reciclagem e arte','Criatividade, cooperação e atenção ao meio ambiente.'),('play','Cinema interativo','Histórias que convidam à reflexão e ao diálogo.'),('people','Rodas de conversa','Escuta e expressão sobre temas do cotidiano.'),('heart','Família e convivência','Encontros, celebrações e aproximação com os responsáveis.'),('chart','Inclusão digital','Informática e novas ferramentas para aprender.'),('pulse','Psicologia','Acompanhamento e ações de promoção do bem-estar.'),('shield','Serviço social','Orientação e apoio para o acesso a direitos e serviços.')]:body+=f'<article class="feature-card"><span class="round-icon">{icon(ic)}</span><h3>{title}</h3><p>{text}</p></article>'
 body+='</div></div></section><section class="section-block"><div class="container site-container">'+heading('Organize a participação','Rotinas e horários')+'<div class="schedule-grid">'
 for title,text in [('Crianças · manhã','Segunda a sexta<br>08h às 11h'),('Crianças · tarde','Segunda a sexta<br>13h às 17h'),('Grupo de mulheres','Terças-feiras<br>13h às 15h'),('Grupo de pessoas idosas','Quintas-feiras<br>14h às 16h'),('Grupo de adolescentes','Sextas-feiras<br>14h às 16h')]:body+=f'<article class="schedule-card"><h3>{title}</h3><p>{text}</p></article>'
 body+=f'''</div><p class="small-note">Confirme os horários e as vagas com a equipe antes de participar.</p></div></section><section class="section-block cream-section"><div class="container site-container"><div class="split-layout"><div class="rounded-photo">{img('informatica')}</div><div>{heading('Nosso espaço','Conhecimento para construir o amanhã.')}<p>A sala de informática faz parte de um ambiente de aprendizagem e convivência, ao lado das atividades culturais e recreativas.</p>{link('Conheça os espaços','galeria.html')}</div></div></div></section>'''+callout('Vamos conversar sobre a sua participação.','Nossa equipe pode orientar você e sua família.',donate=False)
 write_page('convivencia.html','Convivência e vínculos','Atividades, públicos e horários do SCFV da AACI. Arte, cultura, inclusão digital e convivência gratuita.',body,'servicos.html')
 body=intro('Presença, autonomia e afeto.','Atenção à pessoa idosa','Cuidado compartilhado com as famílias para que cada pessoa tenha espaço para conviver e participar.','', 'idosos')
 body+=f'''<section class="section-block"><div class="container site-container"><div class="split-layout"><div>{heading('Casa de Atenção à Pessoa Idosa','Cuidar é também estar junto.')}<p class="lead-copy">Um serviço voltado a pessoas com 60 anos ou mais, com atenção às necessidades individuais e aos vínculos familiares e comunitários.</p><p>O cuidado durante o dia reúne alimentação, oficinas, convivência e acompanhamento de serviço social, psicologia e fisioterapia. A proposta valoriza a autonomia e compartilha com as famílias a tarefa de cuidar.</p>{link('Converse com nossa equipe','contato.html')}</div><div class="value-cards"><article><h3>Convivência</h3><p>Encontros e atividades que ajudam a enfrentar o isolamento e construir relações.</p></article><article><h3>Atenção às famílias</h3><p>Orientação e acompanhamento para apoiar o cuidado no dia a dia.</p></article></div></div></div></section><section class="section-block cream-section"><div class="container site-container">{heading('Histórias de carinho','Afeto que chega de muitas formas.','Registro da entrega de presentes enviados por telespectadores da TV Integração, em 2021.')}<div class="video-reading-width">{yt_player('qHtH_RGf0Ro')}</div></div></section><section class="section-block"><div class="container site-container"><div class="related-banner"><div><p class="eyebrow">Saúde e bem-estar</p><h2>Conheça também a fisioterapia gratuita.</h2><p>Um cuidado que se estende à comunidade.</p></div>{link('Ver atendimento de fisioterapia','fisioterapia.html')}</div></div></section>'''+callout()
 write_page('pessoa-idosa.html','Atenção à pessoa idosa','Convivência, atenção durante o dia e apoio às famílias na Casa de Atenção à Pessoa Idosa da AACI.',body,'servicos.html')
 body=intro('Laços que podem durar uma vida.','Apadrinhamento Afetivo','Pessoas da comunidade podem ser referências de afeto para crianças e adolescentes em acolhimento.','', 'apadrinhamento')
 body+=f'''<section class="section-block"><div class="container site-container"><div class="reading-width">{heading('O que é','Uma relação de presença e pertencimento.')}<p class="lead-copy">O Apadrinhamento Afetivo aproxima crianças e adolescentes em acolhimento de pessoas dispostas a construir vínculos seguros e duradouros.</p><p>O programa é realizado em parceria com a Prefeitura de Juiz de Fora. A equipe acompanha o processo, orienta os interessados e prepara cada etapa de aproximação.</p></div><ol class="steps-grid"><li><span>01</span><h3>Primeiro contato</h3><p>Converse com a AACI para conhecer o programa e esclarecer suas dúvidas.</p></li><li><span>02</span><h3>Avaliação e preparação</h3><p>A equipe orienta sobre documentação, avaliação e encontros de capacitação.</p></li><li><span>03</span><h3>Construção do vínculo</h3><p>A aproximação acontece com acompanhamento da equipe e das instituições envolvidas.</p></li></ol></div></section><section class="section-block cream-section"><div class="container site-container">{heading('Antes de começar','Perguntas sobre o programa')}{accordion([('Por onde começo?','O primeiro passo é procurar a equipe do Apadrinhamento Afetivo para conhecer as orientações e agendar um atendimento inicial.'),('O cadastro já garante a participação?','A participação depende das etapas de acolhida, avaliação, documentação e capacitação. A equipe explica os critérios e acompanha o processo.'),('Como são organizadas as visitas e atividades?','A convivência é combinada com as equipes responsáveis e segue os procedimentos de autorização do programa. Procure a equipe para conhecer as orientações completas.'),('Preciso ter disponibilidade para uma relação contínua?','A proposta é construir vínculos afetivos duradouros. Conversar sobre sua disponibilidade e suas expectativas faz parte da preparação.')],'sponsorFaq')}</div></section><section class="section-block"><div class="container site-container"><div class="contact-highlight"><div>{heading('Fale com o programa','O primeiro passo pode ser uma conversa.')}<p><a href="mailto:apadrinhamento@aaci.org.br">apadrinhamento@aaci.org.br</a></p><p><a href="tel:+553232115475">(32) 3211-5475</a> · <a href="tel:+5532988880665">(32) 98889-0665</a></p></div>{external('Enviar e-mail','mailto:apadrinhamento@aaci.org.br','btn btn-wine')}</div></div></section>'''
 write_page('apadrinhamento.html','Apadrinhamento Afetivo','Conheça o Apadrinhamento Afetivo da AACI, as etapas de participação e os canais da equipe técnica.',body,'servicos.html')
 body=intro('Movimento, cuidado e qualidade de vida.','Fisioterapia gratuita','Atendimento fisioterapêutico gratuito para a comunidade de Juiz de Fora.','', 'fisioterapia')
 body+=f'''<section class="section-block"><div class="container site-container"><div class="split-layout"><div>{heading('Saúde e bem-estar','Um cuidado acessível e próximo.')}<p class="lead-copy">A sala de fisioterapia da AACI reúne estrutura e acompanhamento para apoiar a reabilitação e o bem-estar.</p><p>O atendimento também faz parte do cuidado às pessoas idosas acompanhadas pela instituição. Para saber sobre encaminhamentos e disponibilidade, entre em contato com a equipe.</p>{external('Consultar o atendimento',wa('Olá! Gostaria de informações sobre a fisioterapia gratuita da AACI.'))}</div><aside class="plain-card audience-card"><span class="round-icon">{icon('pulse')}</span><h3>Como buscar orientação</h3><p>Fale com a AACI ou procure sua Unidade Básica de Saúde para se informar sobre o encaminhamento.</p><a href="contato.html">Ver canais de atendimento {icon('arrow')}</a></aside></div></div></section><section class="section-block cream-section"><div class="container site-container">{heading('AACI na imprensa','O cuidado que também é notícia.','Reportagem exibida no MGTV em 4 de julho de 2024, sobre a sala de fisioterapia e o projeto Viver Bem Mais.')}<div class="video-reading-width">{yt_player('uDHRizneRKA')}</div><div class="section-end">{link('Leia a reportagem','noticias/fisioterapia-no-mgtv.html')}</div></div></section>'''+callout()
 write_page('fisioterapia.html','Fisioterapia gratuita','Conheça a fisioterapia gratuita da AACI, os canais de orientação e a reportagem sobre o atendimento.',body,'servicos.html')


def help_page():
 body=intro('Há um jeito de ajudar que combina com você.','Como ajudar','Doar, compartilhar seu tempo e aproximar pessoas são formas de fazer parte dessa história.','', 'campanhas')
 body+=f'''<section class="section-block" id="doar"><div class="container site-container"><div class="split-layout"><div>{heading('Seu gesto importa','Transforme solidariedade em presença.')}<p class="lead-copy">As contribuições ajudam a manter oficinas, alimentação, convivência e atendimento gratuito.</p><p>Escolha o valor que faz sentido para você ou converse com a equipe sobre outras maneiras de contribuir.</p><button type="button" class="btn btn-coral donate-trigger">Escolher um valor {icon('heart')}</button></div><div class="pix-panel"><p class="eyebrow">Pix da AACI</p><h3>Um gesto simples.<br>Muitas possibilidades.</h3><label class="form-label" for="inlinePixKey">Chave Pix · CNPJ</label><div class="input-group"><input id="inlinePixKey" class="form-control" readonly value="11550709000187"><button class="btn btn-wine" type="button" data-copy-pix="11550709000187" data-copy-target="inlinePixKey" data-copy-status="inlinePixStatus">{icon('copy')} Copiar</button></div><p id="inlinePixStatus" class="copy-status" aria-live="polite" role="status"></p><p class="small-note">Associação de Apoio a Crianças e Idosos<br>CNPJ 11.550.709/0001-87</p><details><summary>Doação por transferência</summary><p>Banco Bradesco<br>Agência 2868-1<br>Conta 0010212-1</p></details></div></div></div></section><section class="section-block cream-section" id="voluntariado"><div class="container site-container"><div class="split-layout"><div>{heading('Seu tempo também transforma','Seja voluntário.')}<p class="lead-copy">Compartilhe conhecimentos, habilidades e disponibilidade com a comunidade.</p><p>A história da AACI reúne voluntários em atividades de música, artes, culinária, contação de histórias e outras oficinas. A equipe pode orientar você sobre as possibilidades de participação.</p>{external('Quero ser voluntário','mailto:aacisocial@hotmail.com?subject=Voluntariado%20na%20AACI','btn btn-wine')}</div><div>{yt_player('B2m5VMVNvvg')}</div></div></div></section><section class="section-block"><div class="container site-container">{heading('Participe','Outras formas de estar presente.')}<div class="feature-grid three-columns"><article class="feature-card"><span class="round-icon">{icon('bag')}</span><h3>Doe alimentos e itens</h3><p>Converse com a equipe e conheça as necessidades atuais das campanhas.</p>{external('Consultar necessidades',wa('Olá! Quero saber como doar alimentos e itens para as campanhas da AACI.'))}</article><article class="feature-card"><span class="round-icon">{icon('briefcase')}</span><h3>Seja uma empresa parceira</h3><p>Aproxime sua organização de uma causa e ajude a ampliar o cuidado.</p>{external('Conversar sobre parceria','mailto:aaci-@hotmail.com?subject=Parceria%20com%20a%20AACI')}</article><article class="feature-card"><span class="round-icon">{icon('people')}</span><h3>Conheça o apadrinhamento</h3><p>Saiba como construir um vínculo afetivo acompanhado pela equipe do programa.</p>{link('Conheça o programa','apadrinhamento.html')}</article></div></div></section><section class="section-block cream-section"><div class="container site-container">{heading('Dúvidas comuns','Vamos conversar sobre a sua contribuição.')}{accordion([('Para onde vai minha doação?','As contribuições apoiam as atividades e a estrutura da AACI. Os relatórios e prestações de contas estão disponíveis na <a href="transparencia.html">página de Transparência</a>.'),('Como posso contribuir por Pix?','Use a chave CNPJ 11550709000187 para contribuir com a AACI. Copie a chave acima ou escolha um valor para gerar o QR Code e o Pix Copia e Cola.'),('Quero combinar uma contribuição recorrente. Como faço?','Converse com a equipe pelo <a href="https://wa.me/5532988559201" target="_blank" rel="noopener noreferrer">WhatsApp (32) 98855-9201</a> para conhecer as opções e esclarecer as condições.'),('Como falar sobre comprovantes ou uma doação já realizada?','Entre em contato pelo WhatsApp (32) 98855-9201 ou pelo e-mail <a href="mailto:aaci-@hotmail.com">aaci-@hotmail.com</a>.'),('Como solicitar informações sobre ligações e meus dados?','Você pode <a href="privacidade.html">consultar os canais de privacidade</a> ou falar diretamente com a AACI para registrar sua solicitação.')],'helpFaq')}</div></section>'''
 write_page('como-ajudar.html','Como ajudar','Contribua com a AACI por Pix, transferência, doação de itens, voluntariado e parcerias. Veja os canais oficiais.',body)


def filter_toolbar(categories,scope,years=None):
 html_=f'<div class="filter-toolbar"><div class="filter-search"><label for="{scope}Search">Pesquisar</label><input class="form-control" type="search" id="{scope}Search" data-filter-search placeholder="Busque por assunto ou título"></div>'
 if years:html_+=f'<div><label for="{scope}Year">Ano</label><select class="form-select" id="{scope}Year" data-filter-year><option value="">Todos os anos</option>'+''.join(f'<option value="{y}">{y}</option>' for y in sorted({value for value in years if value},reverse=True))+'</select></div>'
 html_+='</div><div class="filter-pills" role="group" aria-label="Filtrar por assunto"><button class="is-selected" type="button" data-filter-category="" aria-pressed="true">Todos</button>'+''.join(f'<button type="button" data-filter-category="{e(norm(c))}" aria-pressed="false">{e(c)}</button>' for c in categories)+'</div><p class="filter-count" data-filter-count aria-live="polite" role="status"></p>'
 return html_


def transparency():
 body=intro('Uma relação aberta com quem apoia.','Transparência','Conheça os documentos institucionais, os relatórios de atividades e as prestações de contas da AACI.')
 body+='<section class="section-block"><div class="container site-container"><div class="document-summary"><div><strong>26</strong><span>documentos disponíveis</span></div><div><strong>334</strong><span>páginas para consulta</span></div><div><strong>2015–2025</strong><span>memória de atividades e parcerias</span></div></div><div data-filter-scope>'+filter_toolbar(['Relatórios','Prestação de contas','Institucional','Portfólios','Campanhas'],'docs',[d.get('year') for d in DOCS])+'<div class="document-list">'
 group_labels={'relatorios-de-atividades':'Relatórios','prestacao-de-contas':'Prestação de contas','governanca':'Institucional','portfolios':'Portfólios','campanhas':'Campanhas'}
 for d in sorted(DOCS,key=lambda d:(-(d.get('year') or 0),d['titulo'])):
  cat=group_labels.get(d['grupo'],'Prestação de contas');search=norm(d['titulo']+' '+cat+' '+str(d.get('year_label',d.get('year',''))))
  body+=f'<article class="document-row" data-filter-item data-category="{e(norm(cat))}" data-year="{d.get("year") or ""}" data-search="{e(search)}"><span class="round-icon">{icon("file")}</span><div class="document-row-copy"><p class="document-type">{cat} · {e(d.get("year_label",d.get("year") or ""))}</p><h2>{e(d["titulo"])}</h2><p class="small-note">PDF · {d["paginas"]} páginas · {d["bytes"]/1000000:.1f} MB</p><div class="document-actions"><a href="{e(d["path"])}" target="_blank" rel="noopener">Abrir PDF {icon("external")}<span class="visually-hidden">: {e(d["titulo"])} (abre em nova aba)</span></a><a href="{e(d["path"])}" download>Baixar cópia local<span class="visually-hidden"> {e(d["titulo"])}</span></a></div></div></article>'
 body+='</div><p class="empty-state" data-filter-empty hidden>Nenhum documento encontrado. Experimente outro assunto ou ano.</p></div></div></section>'
 missing=EXTERNAL_DOCUMENTS
 body+='<section class="section-block cream-section"><div class="container site-container">'+heading('Mais documentos','Relatórios e publicações da AACI.')+'<ul class="external-documents">'
 for l in missing:body+=f'<li><a href="{e(l["url"])}" target="_blank" rel="noopener noreferrer">{e(l["rotulo"])} {icon("external")}<span class="visually-hidden"> (abre em nova aba)</span></a></li>'
 body+='</ul></div></section>'+callout('Transparência aproxima. Participar transforma.','Conheça nossos canais e converse com a equipe.')
 write_page('transparencia.html','Transparência','Relatórios de atividades, estatuto, ata e prestações de contas da AACI. Consulte ou baixe os documentos PDF.',body)


def news_pages():
 body=intro('O cuidado também conta histórias.','Notícias','Iniciativas, encontros e acontecimentos para acompanhar a atuação da AACI.')
 body+='<section class="section-block"><div class="container site-container"><div data-filter-scope>'+filter_toolbar(list(dict.fromkeys(v[3] for v in ARTICLE_MAP.values())),'news')+'<div class="stories-grid">'+''.join(news_card(n) for n in RESEARCH['noticias'])+'</div><p class="empty-state" data-filter-empty hidden>Nenhuma notícia encontrada. Experimente outro termo.</p></div><div class="related-banner"><div><h2>Quer ver mais de perto?</h2><p>Conheça nossos registros em fotos, vídeos e reportagens.</p></div><div class="button-group">'+link('Galeria de fotos','galeria.html')+link('Vídeos da AACI','videos.html')+'</div></div></div></section>'
 write_page('noticias.html','Notícias','Acompanhe notícias, iniciativas e registros da AACI. Solidariedade, convivência e cuidado em comunidade.',body)
 for n in RESEARCH['noticias']:
  slug,key,media,category=ARTICLE_MAP[n['id']]
  body=f'<section class="article-intro"><div class="container site-container"><nav aria-label="Caminho da página"><ol class="breadcrumb"><li class="breadcrumb-item"><a href="../index.html">Início</a></li><li class="breadcrumb-item"><a href="../noticias.html">Notícias</a></li><li class="breadcrumb-item active" aria-current="page">{category}</li></ol></nav><div class="article-heading"><p class="eyebrow">{category}</p><h1>{e(n["titulo"])}</h1><p class="article-meta"><time datetime="{n["datePublished"][:10]}">{date_label(n["datePublished"])}</time> · AACI</p><p class="page-lead">{EXCERPTS[n["id"]]}</p></div></div></section><article class="article-body"><div class="container site-container"><div class="article-cover">{img(key,"../",lazy=False)}</div><div class="reading-width article-text">'
  paragraphs=n['corpo_paragrafos']
  if paragraphs:body+=''.join(f'<p>{e(t)}</p>' for t in paragraphs)
  else:body+='<p>Assista à mensagem compartilhada pela AACI.</p>'
  body+='</div><div class="article-video">'+(yt_player(media,'../') if media in YT else local_player(media,'../',False))+f'</div><div class="reading-width"><div class="article-share"><span>Compartilhe esta história</span><button class="btn btn-outline-wine" type="button" data-share-page>'+icon('copy')+' Copiar link</button><p class="copy-status" data-share-status aria-live="polite" role="status"></p></div></div></div></article><section class="section-block cream-section"><div class="container site-container">'+heading('Continue acompanhando','Outras histórias da AACI')+'<div class="stories-grid"></div></div></section>'
  # Três sugestões distintas, sem reutilizar a história corrente.
  related=''.join(news_card(other,'../') for other in [o for o in RESEARCH['noticias'] if o['id']!=n['id']][:3])
  body=body.replace('<div class="stories-grid"></div>',f'<div class="stories-grid">{related}</div>')
  write_page(f'noticias/{slug}.html',n['titulo'],EXCERPTS[n['id']],body,'noticias.html')


def gallery_pages():
 categories={'atividades':'Convivência e atividades','campanhas':'Campanhas','idosos':'Pessoa idosa','instalacoes':'Nossos espaços'}
 body=intro('Momentos que aproximam.','Galeria de fotos','Espaços, encontros e ações que fazem parte da nossa história.')
 body+='<section class="section-block"><div class="container site-container"><div data-filter-scope>'+filter_toolbar(sorted({categories.get(a.get('categoria'), 'Comunidade') for a in MAP['galeria']}),'gallery')+'<div class="gallery-grid">'
 for i,a in enumerate(MAP['galeria']):
  label=a.get('caption') or a.get('alt') or 'Registro da AACI';cat=categories.get(a.get('categoria'), 'Comunidade')
  body+=f'<figure class="gallery-tile" data-filter-item data-category="{e(norm(cat))}" data-search="{e(norm(label+" "+cat))}"><a href="{e(a["path"])}" data-gallery-link data-gallery-title="{e(label)}"><img src="{e(a["path"])}" width="{a.get("width",1200)}" height="{a.get("height",800)}" alt="{e(label)}" loading="lazy"><span class="gallery-open" aria-hidden="true">{icon("external")}</span></a><figcaption><span>{e(cat)}</span>{e(label)}</figcaption></figure>'
 body+='</div><p class="empty-state" data-filter-empty hidden>Nenhuma foto encontrada. Experimente outro assunto.</p></div></div></section>'
 body+='<section class="section-block cream-section"><div class="container site-container">'+heading('Memória afetiva','A solidariedade também deixa lembranças.','Um registro de Natal e do apoio às famílias acompanhado pelo canal da AACI.')+'<div class="video-reading-width">'+yt_player('ZWRPjVnhJs0')+'</div></div></section>'
 write_page('galeria.html','Galeria de fotos','Veja fotografias dos espaços, da convivência e das campanhas da AACI. Navegue pela galeria por assunto.',body)
 body=intro('Histórias para assistir e compartilhar.','Vídeos','Reportagens, campanhas e registros da AACI, reunidos por assunto.')
 body+='<section class="section-block"><div class="container site-container"><div data-filter-scope>'+filter_toolbar(['Saúde','Pessoa idosa','Voluntariado','Campanhas','Comunidade'],'video')+'<div class="video-library">'
 cats={'uDHRizneRKA':'Saúde','qHtH_RGf0Ro':'Pessoa idosa','B2m5VMVNvvg':'Voluntariado'}
 for id,v in YT.items():
  cat=cats.get(id,'Campanhas');body+=f'<article class="video-library-card" id="video-{id}" data-filter-item data-category="{norm(cat)}" data-search="{e(norm(v["titulo"]+" "+cat))}">{yt_player(id,caption=False)}<div class="video-library-copy"><p class="eyebrow">{cat}</p><h2>{e(v["titulo"].replace("sextas básicas","cestas básicas"))}</h2></div></article>'
 for id,v in MAP['videos'].items():
  title=v.get('title',v.get('titulo','Vídeo AACI'));cat='Comunidade' if id in {'VID-001','VID-003'} else 'Campanhas'
  body+=f'<article class="video-library-card" data-filter-item data-category="{norm(cat)}" data-search="{e(norm(title+" "+cat))}">{local_player(id,caption=False)}<div class="video-library-copy"><p class="eyebrow">{cat}</p><h2>{e(title)}</h2></div></article>'
 body+='</div><p class="empty-state" data-filter-empty hidden>Nenhum vídeo encontrado. Experimente outro assunto.</p></div></div></section>'
 write_page('videos.html','Vídeos','Assista a reportagens, campanhas e vídeos da AACI. Conteúdo do YouTube e registros locais por assunto.',body)


def contact_page():
 body=intro('Uma conversa pode ser o primeiro passo.','Contato','Fale com a AACI para saber sobre atendimento, participação, doações e parcerias.')
 body+='<section class="section-block"><div class="container site-container"><div class="contact-layout"><div>'+heading('Fale com a gente','Como podemos ajudar você?')+f'<div class="contact-channel"><span class="round-icon">{icon("phone")}</span><div><h3>Atendimento social</h3><a href="tel:+5532984767527">(32) 98476-7527</a></div></div><div class="contact-channel"><span class="round-icon">{icon("heart")}</span><div><h3>Doações e informações</h3><a href="{wa()}" target="_blank" rel="noopener noreferrer">WhatsApp (32) 98855-9201</a></div></div><div class="contact-channel"><span class="round-icon">{icon("mail")}</span><div><h3>E-mail</h3><a href="mailto:aaci-@hotmail.com">aaci-@hotmail.com</a></div></div><div class="contact-address"><h3>Visitas à instituição</h3><p>Rua Doutor Dias da Cruz, 487<br>Nova Era · Juiz de Fora — MG</p><p class="small-note">Fale com a equipe antes da visita para confirmar o local do seu atendimento.</p>{external("Ver localização","https://www.google.com/maps/search/?api=1&query=Rua+Doutor+Dias+da+Cruz+487+Nova+Era+Juiz+de+Fora+MG")}</div></div><div class="contact-form-card"><h2>Prepare sua mensagem</h2><p>Conte como podemos ajudar. Você poderá revisar e enviar a mensagem no WhatsApp.</p><form id="contactForm" novalidate><div class="mb-3"><label class="form-label" for="contactName">Seu nome <span aria-hidden="true">*</span></label><input class="form-control" id="contactName" name="nome" autocomplete="name" required minlength="2" maxlength="100"><div class="invalid-feedback">Informe seu nome.</div></div><div class="mb-3"><label class="form-label" for="contactEmail">E-mail <span class="optional-label">(opcional)</span></label><input class="form-control" id="contactEmail" name="email" type="email" autocomplete="email" maxlength="160"><div class="invalid-feedback">Confira o formato do e-mail.</div></div><div class="mb-3"><label class="form-label" for="contactSubject">Assunto <span aria-hidden="true">*</span></label><select class="form-select" id="contactSubject" name="assunto" required><option value="">Selecione um assunto</option><option>Atendimento e serviços</option><option>Doações e campanhas</option><option>Voluntariado</option><option>Apadrinhamento Afetivo</option><option>Parcerias</option><option>Outras informações</option></select><div class="invalid-feedback">Escolha um assunto.</div></div><div class="mb-3"><label class="form-label" for="contactMessage">Sua mensagem <span aria-hidden="true">*</span></label><textarea class="form-control" id="contactMessage" name="mensagem" rows="4" required minlength="10" maxlength="1800"></textarea><div class="invalid-feedback">Escreva uma mensagem com pelo menos 10 caracteres.</div></div><div class="form-check mb-4"><input class="form-check-input" type="checkbox" id="contactConsent" required><label class="form-check-label" for="contactConsent">Li as informações sobre <a href="privacidade.html">privacidade e uso dos dados</a>.</label><div class="invalid-feedback">Confirme a leitura para continuar.</div></div><button class="btn btn-coral w-100" type="submit" disabled>Preparar mensagem {icon("arrow")}</button><div class="contact-result" id="contactResult" hidden><p id="contactFormStatus" role="status" aria-live="polite"></p><a class="btn btn-wine w-100" id="contactWhatsapp" target="_blank" rel="noopener noreferrer">Continuar no WhatsApp {icon("external")}</a></div></form></div></div></div></section>'
 body+=f'''<section class="section-block cream-section"><div class="container site-container">{heading('Equipes dos programas','Procure o canal mais próximo do que você precisa.')}<div class="team-grid"><article class="plain-card"><h3>Convivência e vínculos</h3><p><a href="mailto:aacisocial@hotmail.com">aacisocial@hotmail.com</a></p><p><a href="tel:+553232264832">(32) 3226-4832</a></p>{link('Conheça o serviço','convivencia.html')}</article><article class="plain-card"><h3>Apadrinhamento Afetivo</h3><p><a href="mailto:apadrinhamento@aaci.org.br">apadrinhamento@aaci.org.br</a></p><p><a href="tel:+553232115475">(32) 3211-5475</a> · <a href="tel:+5532988880665">(32) 98889-0665</a></p>{link('Conheça o programa','apadrinhamento.html')}</article><article class="plain-card"><h3>Projetos e parcerias</h3><p><a href="mailto:projetosaaci@hotmail.com">projetosaaci@hotmail.com</a></p><p>Converse sobre iniciativas e novas possibilidades de colaboração.</p>{link('Outras formas de ajudar','como-ajudar.html')}</article></div></div></section>'''
 write_page('contato.html','Contato','Telefones, e-mails e canais da AACI. Prepare sua mensagem para conversar com a equipe pelo WhatsApp.',body)


def privacy_and_jobs():
 body=intro('Informação clara também é cuidado.','Privacidade','Conheça como funcionam os canais deste site e onde falar sobre seus dados.')
 body+='<section class="section-block"><div class="container site-container"><div class="reading-width prose">'
 for title,text in [('Sobre a AACI','A Associação de Apoio a Crianças e Idosos é uma organização sem fins lucrativos, inscrita no CNPJ 11.550.709/0001-87.'),('Mensagem de contato','O formulário de contato prepara uma mensagem com os dados que você informa. Ao escolher continuar, ela é aberta no WhatsApp para sua revisão e envio. O e-mail é opcional. Utilize o campo de mensagem para dúvidas gerais e evite incluir documentos ou informações sensíveis.'),('Vídeos e serviços externos',PRIVACY_EXTERNAL_TEXT),('Seus direitos e solicitações','Para esclarecer dúvidas sobre privacidade, solicitar informações ou tratar de seus dados, entre em contato com a AACI pelo e-mail <a href="mailto:aaci-@hotmail.com">aaci-@hotmail.com</a>.')]:body+=f'<h2>{title}</h2><p>{text}</p>'
 body+='</div></div></section>'
 write_page('privacidade.html','Privacidade e seus dados','Conheça os canais de privacidade da AACI e o funcionamento do contato, dos vídeos e dos serviços externos.',body)
 body=intro('Seu trabalho pode fazer parte dessa história.','Trabalhe conosco','Acompanhe os canais de oportunidades e saiba como apresentar seu interesse à AACI.')
 body+='<section class="section-block"><div class="container site-container"><div class="split-layout"><div>'+heading('Faça parte','Talento e cuidado caminham juntos.')+'<p class="lead-copy">Nossa equipe reúne diferentes conhecimentos para acolher, orientar e cuidar da comunidade.</p><p>Converse com nossa equipe para saber sobre oportunidades de trabalho e receber orientações para apresentar sua candidatura.</p>'+link('Fale com a equipe','contato.html',style='btn btn-coral')+'</div><aside class="plain-card"><h3>Encontre o seu jeito de participar</h3><p>Você também pode compartilhar seu tempo e seus conhecimentos como voluntário.</p>'+link('Conheça o voluntariado','como-ajudar.html#voluntariado')+'</aside></div></div></section>'+callout('Vamos construir essa história juntos.','Converse com a AACI sobre participação e oportunidades.',donate=False)
 write_page('trabalhe-conosco.html','Trabalhe conosco','Saiba como apresentar sua candidatura à AACI e conheça outras formas de participação.',body)


def main():
 global MAP,DOCS
 MAP=json.loads((DATA/'asset-map.json').read_text(encoding='utf-8'))
 DOCS=json.loads((DATA/'document-map.json').read_text(encoding='utf-8'))['documentos']
 for key in ['hero','convivencia','idosos','apadrinhamento','fisioterapia','informatica','campanhas','cozinha','fachada','refeitorio','sala-atividades','noticia-cozinha','noticia-moveis','noticia-mensagem','noticia-doacao','noticia-fisioterapia']:
  assert key in MAP['imagens'],key
 home();about();services();service_details();help_page();transparency();news_pages();gallery_pages();contact_page();privacy_and_jobs()
 (DATA/'site-pages.json').write_text(json.dumps({'paginas':BUILT,'noticias':[{**n,'pagina':'noticias/'+ARTICLE_MAP[n['id']][0]+'.html'} for n in RESEARCH['noticias']],'atualizacao':'2026-11-13'},ensure_ascii=False,indent=2),encoding='utf-8')
 print(f'Site gerado: {len(BUILT)} páginas HTML. Documentos: {len(DOCS)}. Vídeos YouTube: {len(YT)}.')
 for path in BUILT:print(path)


if __name__=='__main__':main()
